function observations(edit=''){let e=db.observations.find(x=>x.id===edit),hist=db.observations.filter(x=>x.year===db.activeYear).map(x=>`<div class="recordCard"><div><b>${x.date} ${x.time} · ${x.species}</b><br>${x.animalClass} · ${x.count} djur · ${x.place}<small>Observatör: ${x.observerName}</small></div><div class="recordActions"><button onclick="observations('${x.id}')">Ändra</button><button class="danger" onclick="delObs('${x.id}')">Radera</button></div></div>`).join('')||'<p class="muted">Inga observationer.</p>',form=`<div class="stackForm"><input id="obsId" type="hidden" value="${e?.id||''}"><label>Datum<input id="obsDate" type="date" value="${e?.date||new Date().toISOString().slice(0,10)}"></label><label>Tid<input id="obsTime" type="time" step="1800" value="${e?.time||'06:00'}"></label><label>Observatör<select id="obsObserver">${db.members.map(m=>`<option value="${m.id}" ${e?.observerId===m.id?'selected':''}>${m.name}</option>`).join('')}<option value="external" ${e?.observerType==='external'?'selected':''}>Annan person</option></select></label><label id="obsExternalBox" hidden>Namn<input id="obsExternal" value="${e?.observerType==='external'?esc(e.observerName):''}"></label><label>Djurslag<select id="obsSpecies">${mainSpecies.map(x=>`<option ${e?.species===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Klass<select id="obsClass"></select></label><label>Antal djur i flocken<input id="obsCount" type="number" min="1" value="${e?.count||1}"></label><label>Pass<select id="obsPass"></select></label><label>Riktning<select id="obsDirection">${['Okänd','N','NO','O','SO','S','SV','V','NV'].map(x=>`<option ${e?.direction===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="windFields"><label>Vind från<select id="obsWindDirection">${dirs.map(x=>`<option ${e?.windDirection===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Vindstyrka m/s<input id="obsWindSpeed" type="number" min="0" step="0.1" value="${e?.windSpeed??0}"></label></div><label>Kommentar<textarea id="obsComment">${esc(e?.comment||'')}</textarea></label><button id="saveObs">${e?'Spara ändringar':'Registrera observation'}</button></div>`;shell('Viltobservationer',tabs(form,hist,e?'reg':'hist'));passOptions($('#obsPass'),e?.place);bindTabs();let fill=()=>$('#obsClass').innerHTML=cfg[$('#obsSpecies').value].map(x=>`<option ${e?.animalClass===x[0]?'selected':''}>${x[0]}</option>`).join('');fill();$('#obsSpecies').onchange=fill;let toggle=()=>$('#obsExternalBox').hidden=$('#obsObserver').value!=='external';toggle();$('#obsObserver').onchange=toggle;$('#saveObs').onclick=()=>{let id=$('#obsId').value,old=db.observations.find(x=>x.id===id),ext=$('#obsObserver').value==='external',o={id:id||uid('obs'),year:db.activeYear,date:$('#obsDate').value,time:$('#obsTime').value,observerType:ext?'external':'member',observerId:ext?null:$('#obsObserver').value,observerName:ext?($('#obsExternal').value.trim()||'Ej angivet'):member($('#obsObserver').value).name,species:$('#obsSpecies').value,animalClass:$('#obsClass').value,count:Math.max(1,+$('#obsCount').value||1),place:$('#obsPass').value,direction:$('#obsDirection').value,windDirection:$('#obsWindDirection').value,windSpeed:Math.max(0,+$('#obsWindSpeed').value||0),comment:$('#obsComment').value,latitude:old?.latitude||null,longitude:old?.longitude||null,gridCellId:old?.gridCellId||null,createdAt:old?.createdAt||now(),updatedAt:now()};if(old)db.observations[db.observations.indexOf(old)]=o;else db.observations.unshift(o);save();observations();toast(old?'Observationen uppdaterad':'Observationen registrerad')}}window.delObs=id=>{if(confirm('Radera observationen?')){db.observations=db.observations.filter(x=>x.id!==id);save();observations()}}

let huntMap=null,mapLayers=[],satelliteLayer=null,streetLayer=null,draftLayer=null,boundaryLayer=null,boundaryHandles=[],mapMode='point',draftTrack=[];
const dirs=['Okänd','N','NO','O','SO','S','SV','V','NV'],dirDeg={N:0,NO:45,O:90,SO:135,S:180,SV:225,V:270,NV:315};
function loadLeaflet(cb){if(window.L)return cb();if(document.querySelector('#leafletCss'))return setTimeout(()=>loadLeaflet(cb),100);let c=document.createElement('link');c.id='leafletCss';c.rel='stylesheet';c.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';document.head.appendChild(c);let j=document.createElement('script');j.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';j.onload=cb;j.onerror=()=>{$('#mapCanvas').innerHTML='<div class="mapError">Kartbiblioteket kunde inte hämtas. Sparad viltrapportering finns kvar lokalt.</div>'};document.head.appendChild(j)}
function options(a,selected=''){return a.map(x=>`<option ${x===selected?'selected':''}>${x}</option>`).join('')}
function mapview(){shell('Karta, vind och viltspår',`<p class="muted">Allt sparas i samma viltrapportering. Punkt, spår, flockstorlek och vind blir en gemensam observation.</p><div class="mapToolbar"><button id="pointMode" class="active">Observation</button><button id="trackMode" class="secondary">Viltspår</button><button id="boundaryMode" class="secondary">Justera gräns</button><button id="forecastMode" class="secondary">Jaktprognos</button><button id="finishTrack" class="secondary wide" hidden>Avsluta spår</button><button id="saveBoundary" class="secondary wide" hidden>Spara gräns</button></div><div id="mapLegend" class="mapLegend" hidden>● Observation　━ Viltspår　● Spårtecken　━ Gräns　⌖ Sittplats　〰 Vind</div><div id="mapCanvas" class="huntMap"><div class="mapLoading">Laddar satellitkarta…</div></div><div id="mapForm" class="mapReport card" hidden><div class="row"><h3 id="mapFormTitle">Ny observation</h3><button id="cancelMap" class="secondary">Avbryt</button></div><label>Djurslag<select id="mapSpecies">${options(mainSpecies)}</select></label><label>Klass<select id="mapClass"></select></label><label>Antal djur i flocken<input id="mapCount" type="number" min="1" value="1"></label><label>Observatör<select id="mapObserver">${db.members.filter(x=>x.active!==false).map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}<option value="external">Annan observatör</option></select></label><label id="mapExternalObserverBox" hidden>Namn<input id="mapExternalObserver"></label><div class="two"><label>Djurens riktning<select id="mapDirection">${options(dirs)}</select></label><label>Aktivitet<select id="mapActivity">${options(['Står still','Betar','Går','Travar','Springer'])}</select></label></div><div class="windFields"><label>Vind från<select id="mapWindDirection">${options(dirs)}</select></label><label>Vindstyrka m/s<input id="mapWindSpeed" type="number" min="0" max="40" step="0.1" value="3"></label></div><label>Kommentar<textarea id="mapComment" placeholder="Exempel: gick längs skogskanten"></textarea></label><button id="saveMapReport">Spara i gemensam viltrapportering</button></div><div id="forecastPanel" class="card mapReport" hidden><h3>Var är chansen störst?</h3><label>Viltslag<select id="forecastSpecies">${options(mainSpecies)}</select></label><div class="two"><label>Datum<input id="forecastDate" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Tid<input id="forecastTime" type="time" value="${new Date().toTimeString().slice(0,5)}"></label></div><div class="windFields"><label>Vind från<select id="forecastWind">${options(dirs)}</select></label><label>Vindstyrka m/s<input id="forecastSpeed" type="number" min="0" value="3"></label></div><button id="runForecast">Analysera historiken</button><div id="forecastResult"></div></div><h3>Senaste kartlagda observationer</h3><div id="mappedList"></div>`);let fillClass=()=>$('#mapClass').innerHTML=options(cfg[$('#mapSpecies').value].map(x=>x[0]));fillClass();$('#mapSpecies').onchange=fillClass;$('#pointMode').onclick=()=>setMapMode('point');$('#trackMode').onclick=()=>setMapMode('track');$('#boundaryMode').onclick=()=>setMapMode('boundary');$('#forecastMode').onclick=()=>setMapMode('forecast');$('#finishTrack').onclick=finishTrack;$('#saveBoundary').onclick=saveBoundary;$('#runForecast').onclick=runForecast;$('#cancelMap').onclick=()=>{$('#mapForm').hidden=true;draftTrack=[];if(draftLayer)draftLayer.setLatLngs([])};loadLeaflet(initHuntMap);renderMappedList()}
function toggleBaseLayer(){if(!huntMap)return;let c=huntMap.getCenter(),z=huntMap.getZoom(),street=huntMap.hasLayer(streetLayer);if(street){huntMap.removeLayer(streetLayer);satelliteLayer.addTo(huntMap);localStorage.setItem('jaktlaget-map-layer','satellite');$('#baseLayerToggle').textContent='Karta'}else{huntMap.removeLayer(satelliteLayer);streetLayer.addTo(huntMap);localStorage.setItem('jaktlaget-map-layer','street');$('#baseLayerToggle').textContent='Satellit'}huntMap.setView(c,z)}function initHuntMap(){let el=$('#mapCanvas');if(!el)return;el.innerHTML='';if(huntMap)huntMap.remove();huntMap=L.map(el,{zoomControl:true}).setView([58.6205,16.1825],14);satelliteLayer=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,attribution:'Esri'});streetLayer=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'OpenStreetMap'});let pref=localStorage.getItem('jaktlaget-map-layer')||'satellite';(pref==='street'?streetLayer:satelliteLayer).addTo(huntMap);$('#baseLayerToggle').textContent=pref==='street'?'Satellit':'Karta';draftLayer=L.polyline([],{color:'#52e482',weight:5,dashArray:'6 8'}).addTo(huntMap);drawBoundary(false);huntMap.fitBounds(boundaryLayer.getBounds(),{padding:[18,18]});huntMap.on('click',e=>{if(mapMode==='point'){draftTrack=[e.latlng];openMapForm(false)}else if(mapMode==='track'){draftTrack.push(e.latlng);draftLayer.setLatLngs(draftTrack);$('#finishTrack').hidden=draftTrack.length<2}});drawMapData()}
function drawBoundary(edit){if(boundaryLayer)huntMap.removeLayer(boundaryLayer);boundaryHandles.forEach(x=>huntMap.removeLayer(x));boundaryHandles=[];boundaryLayer=L.polygon(db.mapData.boundary,{color:'#2997ff',weight:4,fillColor:'#2997ff',fillOpacity:.08}).addTo(huntMap);if(edit)db.mapData.boundary.forEach((pt,i)=>{let h=L.marker(pt,{draggable:true,icon:L.divIcon({className:'boundaryHandle',html:'<span></span>',iconSize:[22,22]})}).addTo(huntMap);h.on('drag',e=>{let q=e.target.getLatLng();db.mapData.boundary[i]=[q.lat,q.lng];boundaryLayer.setLatLngs(db.mapData.boundary)});boundaryHandles.push(h)})}
function setMapMode(m){mapMode=m;draftTrack=[];if(draftLayer)draftLayer.setLatLngs([]);['point','track','boundary','forecast'].forEach(x=>{let b=$('#'+x+'Mode');b.classList.toggle('active',m===x);b.classList.toggle('secondary',m!==x)});$('#finishTrack').hidden=true;$('#saveBoundary').hidden=m!=='boundary';$('#forecastPanel').hidden=m!=='forecast';$('#mapForm').hidden=true;if(huntMap)drawBoundary(m==='boundary');if(m==='point')toast('Tryck där djuren sågs');if(m==='track')toast('Tryck ut djurens väg, minst två punkter');if(m==='boundary')toast('Dra de blå hörnpunkterna och spara');}
function finishTrack(){if(draftTrack.length<2)return toast('Lägg minst två punkter');openMapForm(true)}
function saveBoundary(){save();drawBoundary(false);setMapMode('point');toast('Markgränsen sparades')}
function openMapForm(track){$('#mapForm').hidden=false;$('#mapFormTitle').textContent=track?'Nytt viltspår':'Ny kartobservation';$('#saveMapReport').onclick=()=>saveMapObservation(track);fetchMapWeather();$('#mapDate').onchange=fetchMapWeather;$('#mapTime').onchange=fetchMapWeather;$('#mapForm').scrollIntoView({behavior:'smooth',block:'start'})}
async function fetchMapWeather(){if(!draftTrack.length)return;try{let p=draftTrack[0],target=new Date($('#mapDate').value+'T'+$('#mapTime').value),u=`https://api.open-meteo.com/v1/forecast?latitude=${p.lat}&longitude=${p.lng}&hourly=wind_speed_10m,wind_direction_10m&wind_speed_unit=ms&timezone=Europe%2FStockholm&forecast_days=16`,j=await(await fetch(u)).json(),i=j.hourly.time.reduce((b,t,k)=>Math.abs(new Date(t)-target)<Math.abs(new Date(j.hourly.time[b])-target)?k:b,0),wd=j.hourly.wind_direction_10m[i];$('#mapWindDirection').value=dirs[1+Math.round(wd/45)%8];$('#mapWindSpeed').value=Number(j.hourly.wind_speed_10m[i]).toFixed(1)}catch(e){}}function compass(a,b){let d=Math.atan2(b.lng-a.lng,b.lat-a.lat)*180/Math.PI;if(d<0)d+=360;return dirs[1+Math.round(d/45)%8]}
function saveMapObservation(isTrack){let first=draftTrack[0],last=draftTrack[draftTrack.length-1],m=$('#mapObserver').value==='external'?null:member($('#mapObserver').value),dir=isTrack?compass(first,last):$('#mapDirection').value,o={id:uid('obs'),year:db.activeYear,date:new Date().toISOString().slice(0,10),time:new Date().toTimeString().slice(0,5),observerType:'member',observerId:m.id,observerName:m.name,species:$('#mapSpecies').value,animalClass:$('#mapClass').value,count:Math.max(1,+$('#mapCount').value||1),place:'Kartposition',direction:dir,activity:$('#mapActivity').value,windDirection:$('#mapWindDirection').value,windSpeed:Math.max(0,+$('#mapWindSpeed').value||0),comment:$('#mapComment').value,latitude:first.lat,longitude:first.lng,track:isTrack?draftTrack.map(x=>({lat:x.lat,lng:x.lng})):[],createdAt:now(),updatedAt:now()};db.observations.unshift(o);audit(isTrack?'Viltspår registrerat':'Kartobservation registrerad',`${o.species}, ${o.count} djur, vind ${o.windDirection} ${o.windSpeed} m/s`);save();$('#mapForm').hidden=true;draftTrack=[];if(draftLayer)draftLayer.setLatLngs([]);drawMapData();renderMappedList();toast(isTrack?'Spår och vind sparades':'Observation och vind sparades')}
function windSvg(o){if(!o.windDirection||o.windDirection==='Okänd')return '';let d=dirDeg[o.windDirection]||0,len=55+Math.min(45,(+o.windSpeed||0)*4);return `<div class="windBadge"><span class="windArrow" style="--rot:${d+180}deg;--len:${len}px">➤</span><b>Vind från ${o.windDirection}</b><small>${o.windSpeed||0} m/s</small></div>`}
function drawMapData(){if(!huntMap)return;mapLayers.forEach(x=>huntMap.removeLayer(x));mapLayers=[];db.observations.filter(o=>Number.isFinite(o.latitude)&&Number.isFinite(o.longitude)).forEach(o=>{let html=`<b>${esc(o.species)} · ${o.count} djur</b><br>${esc(o.date)} ${esc(o.time||'')}<br>Djur: ${esc(o.direction||'Okänd')}<br>${windSvg(o)}`;let mk=L.circleMarker([o.latitude,o.longitude],{radius:Math.min(15,7+o.count/2),color:'#fff',weight:2,fillColor:'#43db79',fillOpacity:.9}).bindPopup(html).addTo(huntMap);mapLayers.push(mk);if(o.track&&o.track.length>1){let line=L.polyline(o.track.map(x=>[x.lat,x.lng]),{color:'#ffd166',weight:4}).bindPopup(html+'<br>Viltspår');line.addTo(huntMap);mapLayers.push(line)}if(o.windDirection&&o.windDirection!=='Okänd'){let km=.00016*(45+Math.min(55,(+o.windSpeed||0)*5)),a=(dirDeg[o.windDirection]+180)*Math.PI/180,d=[o.latitude+Math.cos(a)*km,o.longitude+Math.sin(a)*km/Math.cos(o.latitude*Math.PI/180)];let w=L.polyline([[o.latitude,o.longitude],d],{color:'#62c8ff',weight:5,opacity:.9,dashArray:'12 7'}).addTo(huntMap);mapLayers.push(w)}})}
function renderMappedList(){let e=$('#mappedList');if(!e)return;let a=db.observations.filter(o=>Number.isFinite(o.latitude)&&Number.isFinite(o.longitude)).slice(0,8);e.innerHTML=a.map(o=>`<div class="recordCard"><div><b>${esc(o.species)} · ${o.count} djur</b><br>${esc(o.date)} ${esc(o.time||'')} · ${o.track&&o.track.length>1?'Spår':'Punkt'}<small>Djur ${esc(o.direction||'Okänd')} · Vind från ${esc(o.windDirection||'ej angiven')} ${o.windSpeed??''} m/s</small></div><button class="danger" onclick="deleteMappedObs('${o.id}')">Radera</button></div>`).join('')||'<p class="muted">Inga kartlagda observationer ännu.</p>'}
function runForecast(){let sp=$('#forecastSpecies').value,wind=$('#forecastWind').value,time=$('#forecastTime').value,h=+time.split(':')[0],all=db.observations.filter(o=>o.species===sp&&Number.isFinite(o.latitude)&&Number.isFinite(o.longitude)),scored=all.map(o=>{let oh=+(o.time||'12:00').split(':')[0],score=1+Math.max(0,6-Math.abs(oh-h));if(wind!=='Okänd'&&o.windDirection===wind)score+=6;score+=Math.min(5,(+o.count||1)/2);return {o,score}}).sort((a,b)=>b.score-a.score).slice(0,3);mapLayers.filter(x=>x._forecast).forEach(x=>huntMap.removeLayer(x));if(!scored.length){$('#forecastResult').innerHTML='<p class="muted">Det finns ännu inga kartlagda observationer för valt viltslag. Prognosen blir användbar när fler observationer har sparats.</p>';return}let max=scored[0].score;scored.forEach((x,i)=>{let c=i===0?'#43db79':i===1?'#ffd166':'#ff8b70',r=90+(x.score/max)*130,z=L.circle([x.o.latitude,x.o.longitude],{radius:r,color:c,fillColor:c,fillOpacity:.18,weight:3}).addTo(huntMap);z._forecast=true;mapLayers.push(z)});huntMap.fitBounds(L.latLngBounds(scored.map(x=>[x.o.latitude,x.o.longitude])),{padding:[45,45]});$('#forecastResult').innerHTML=`<div class="forecastSummary"><b>Historikbaserad bedömning</b><p>Gröna området har bäst matchning mot valt viltslag, tid, flockstorlek och vind i sparade observationer.</p><small>Underlag: ${all.length} kartlagda observationer. Resultatet är beslutsstöd, inte en garanti.</small></div>`}
window.deleteMappedObs=id=>{if(confirm('Radera observationen även från viltrapporteringen?')){db.observations=db.observations.filter(x=>x.id!==id);save();drawMapData();renderMappedList()}}

function huntstats(){let hs=db.hunts.filter(x=>x.year===db.activeYear),md={},gd={};hs.forEach(h=>{h.participants.forEach(x=>md[x]=(md[x]||0)+1);h.guests.forEach(x=>gd[x]=(gd[x]||0)+1)});let typeRows=['Vakjakt','Pyrschjakt','Drevjakt'].map(t=>{let a=hs.filter(x=>x.type===t);return `<div class="statLine"><span>${t}</span><b>${a.length} jakter · ${a.reduce((n,x)=>n+x.participants.length+x.guests.length,0)} jaktdagar</b></div>`}).join('');shell('Jaktstatistik',`<div class="subKpis four"><div><span>Jakter</span><b>${hs.length}</b></div><div><span>Medlemsdagar</span><b>${Object.values(md).reduce((a,b)=>a+b,0)}</b></div><div><span>Gästdagar</span><b>${Object.values(gd).reduce((a,b)=>a+b,0)}</b></div><div><span>Lagets jaktdagar</span><b>${Object.values(md).reduce((a,b)=>a+b,0)+Object.values(gd).reduce((a,b)=>a+b,0)}</b></div></div><h3>Jaktformer</h3>${typeRows}<h3>Medlemmar</h3>${db.members.map(m=>`<div class="statLine"><span>${m.name}</span><b>${md[m.id]||0}</b></div>`).join('')}<h3>Gäster</h3>${Object.entries(gd).map(x=>`<div class="statLine"><span>${esc(x[0])}</span><b>${x[1]}</b></div>`).join('')||'<p class="muted">Inga gäster.</p>'}`)}
function obsstats(){let a=db.observations.filter(x=>x.year===db.activeYear),s={};a.forEach(x=>{s[x.species]=s[x.species]||[0,0];s[x.species][0]++;s[x.species][1]+=x.count});shell('Observationsstatistik',`<p class="muted">Observerade djur är inte samma sak som unika djur. Samma djur kan ha observerats flera gånger.</p><div class="subKpis"><div><span>Observationer</span><b>${a.length}</b></div><div><span>Observerade djur</span><b>${a.reduce((n,x)=>n+x.count,0)}</b></div></div>${Object.entries(s).map(x=>`<div class="statLine"><span>${x[0]}</span><b>${x[1][0]} obs · ${x[1][1]} djur</b></div>`).join('')}`)}
function discards(){let x=db.animals.filter(a=>a.year===db.activeYear&&(a.discarded||a.species==='Annat'));shell('Kassation och övrigt vilt',x.map(a=>`<div class="recordCard"><div><b>${a.species==='Annat'?(a.otherSpecies||'Annat'):a.species} · ${a.type}</b><br>${a.date} · ${a.place}<small>${a.discarded?'Kasserat: '+a.discardReason:'Övrigt vilt'}</small></div><button onclick="editAnimal('${a.id}')">Ändra</button></div>`).join('')||'<p class="muted">Inga poster.</p>')}
function goals(){let specs=mainSpecies;let html=`<label>Djurslag<select id="goalSpecies">${specs.map(x=>`<option>${x}</option>`).join('')}</select></label><div id="goalBody"></div>`;shell('Avskjutningsmål',html);$('#goalSpecies').onchange=drawGoal;drawGoal()}function drawGoal(){let sp=$('#goalSpecies').value,g=db.goals[sp],a=normalAnimals().filter(x=>x.species===sp).sort((x,y)=>x.date.localeCompare(y.date)),ad=a.filter(x=>x.age==='Vuxen').length,yo=a.length-ad,pts=a.map((x,i)=>`${10+i*(80/Math.max(1,a.length-1))},${120-i*(90/Math.max(1,a.length))}`).join(' ');$('#goalBody').innerHTML=`<div class="goalGrid"><label>Mål vuxen<input id="goalAdult" type="number" value="${g.adult}"></label><label>Mål ungdjur<input id="goalYoung" type="number" value="${g.young}"></label></div><button id="saveGoal">Spara mål</button>${goalRow('Vuxen',ad,g.adult)}${goalRow('Ungdjur',yo,g.young)}<p class="muted">Period ${g.start} till ${g.end}. Föregående jaktår visas när historiska data finns.</p><div class="timeline"><svg viewBox="0 0 100 140"><line x1="5" y1="125" x2="95" y2="125" stroke="#547"/><polyline points="${pts}" fill="none" stroke="#43db79" stroke-width="3"/></svg></div>`;$('#saveGoal').onclick=()=>{g.adult=Math.max(0,+$('#goalAdult').value||0);g.young=Math.max(0,+$('#goalYoung').value||0);save();drawGoal();toast('Målet sparat')}}function goalRow(n,v,t){return `<div class="goalRow"><div><b>${n}</b><span>${v} av ${t}</span></div><i><b style="width:${t?Math.min(100,v/t*100):0}%"></b></i></div>`}
function passview(){shell('Passöversikt',`<label>Välj pass<select id="viewPass">${db.passes.map(x=>`<option>${esc(x.name)}</option>`).join('')}</select></label><div id="passViewBody"></div>`);$('#viewPass').onchange=drawPassView;drawPassView()}function drawPassView(){let p=$('#viewPass').value,a=db.animals.filter(x=>x.place===p),h=db.hunts.filter(x=>x.place===p),o=db.observations.filter(x=>x.place===p);$('#passViewBody').innerHTML=`<div class="subKpis twoKpi"><div><span>Fällda</span><b>${a.length}</b></div><div><span>Observationer</span><b>${o.length}</b></div></div><h3>Fällt vilt</h3>${a.map(x=>`<div class="statLine"><span>${x.date} ${x.species}</span><b>${x.type}</b></div>`).join('')||'<p class="muted">Inga poster.</p>'}<h3>Jaktformer</h3>${['Vakjakt','Pyrschjakt','Drevjakt'].map(t=>`<div class="statLine"><span>${t}</span><b>${h.filter(x=>x.type===t).length}</b></div>`).join('')}`}
function infoSymbol(p){return p==='critical'?'⛔':p==='important'?'⚠':'ℹ'}function infoLabel(p){return p==='critical'?'Måste läsas':p==='important'?'Viktig information':'Allmän information'}function infoCard(x){return `<div class="infoCard info-${x.priority||'general'}"><span class="infoSymbol">${infoSymbol(x.priority)}</span><div><b>${infoLabel(x.priority)}</b><p>${esc(x.text)}</p><small>${esc(x.author||'Ej angivet')} · ${x.date?new Date(x.date).toLocaleString('sv-SE'):''}</small></div></div>`}
function info(){let posts=(db.infoPosts||[]).slice().reverse(),authors=db.members.filter(x=>x.active!==false);shell('Information',`<div class="infoList">${posts.length?posts.map(x=>infoCard(x)+`<button class="danger infoDelete" onclick="deleteInfo('${x.id}')">Radera</button>`).join(''):'<p class="muted">Ingen information har lagts till.</p>'}</div><div class="stackForm infoForm"><label>Författare<select id="infoAuthor">${authors.map(m=>`<option>${esc(m.name)}</option>`).join('')}</select></label><label>Prioritet<select id="infoPriority"><option value="general">ℹ Allmän information</option><option value="important">⚠ Viktig information</option><option value="critical">⛔ Måste läsas</option></select></label><label>Information<textarea id="teamInfo" rows="6"></textarea></label><button id="saveInfo">Lägg till information</button></div>`);$('#saveInfo').onclick=()=>{let text=$('#teamInfo').value.trim();if(!text)return toast('Skriv informationen');db.infoPosts=db.infoPosts||[];db.infoPosts.push({id:uid('info'),text,author:$('#infoAuthor').value,priority:$('#infoPriority').value,date:now()});save();info();toast('Information publicerad')}}
window.deleteInfo=id=>{if(confirm('Radera informationen?')){db.infoPosts=db.infoPosts.filter(x=>x.id!==id);save();info()}}
function chat(){let authors=db.members.filter(x=>x.active!==false);shell('Chatt',`${db.messages.map(x=>`<div class="event chatEvent"><b>${esc(x.author||'Ej angivet')}</b><span>${esc(x.text)}</span><small>${x.date?new Date(x.date).toLocaleString('sv-SE'):''}</small></div>`).join('')}<div class="stackForm"><label>Vem skriver?<select id="chatAuthor">${authors.map(m=>`<option>${esc(m.name)}</option>`).join('')}</select></label><label>Meddelande<input id="chatText" placeholder="Meddelande"></label><button id="sendChat">Skicka</button></div>`);$('#sendChat').onclick=()=>{let t=$('#chatText').value.trim();if(t){db.messages.push({id:uid('msg'),author:$('#chatAuthor').value,text:t,date:now()});save();chat()}}}
function calendar(){let cards=db.events.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(x=>`<div class="calendarCard"><div><b>${x.date}</b><span>${esc(x.title)}</span></div><button class="danger" onclick="deleteEvent('${x.id}')">Radera</button></div>`).join('')||'<p class="muted">Inga aktiviteter.</p>';shell('Kalender',`<div class="calendarList">${cards}</div><div class="stackForm calendarForm"><label>Datum<input id="eventDate" type="date"></label><label>Aktivitet<input id="eventTitle" placeholder="Aktivitet"></label><button id="addEvent">Lägg till</button></div>`);$('#addEvent').onclick=()=>{if($('#eventDate').value&&$('#eventTitle').value.trim()){db.events.push({id:uid('event'),date:$('#eventDate').value,title:$('#eventTitle').value.trim()});save();calendar()}}}
window.deleteEvent=id=>{if(confirm('Radera aktiviteten?')){db.events=db.events.filter(x=>x.id!==id);save();calendar()}}
function contacts(){shell('Kontakter',`<div class="contactList">${db.members.map(x=>`<button onclick="openContact('${x.id}')"><b>${x.name}</b><span>Visa kontaktinformation</span></button>`).join('')}</div>`)}window.openContact=id=>{let m=member(id);shell(m.name,`<button class="backBtn" onclick="contacts()">‹ Kontakter</button><div id="contactView" class="contactDetail"><div><span>Telefon</span><b>${esc(m.phone||'Ej angivet')}</b></div><div><span>E-post</span><b>${esc(m.email||'Ej angivet')}</b></div><div><span>Kommentar</span><b>${esc(m.comment||'Ej angivet')}</b></div><button id="editContact">Redigera</button></div><div id="contactEdit" class="stackForm" hidden><input id="cPhone" value="${esc(m.phone)}"><input id="cEmail" value="${esc(m.email)}"><textarea id="cComment">${esc(m.comment)}</textarea><button id="saveContact">Spara</button></div>`);$('#editContact').onclick=()=>{$('#contactView').hidden=true;$('#contactEdit').hidden=false};$('#saveContact').onclick=()=>{m.phone=$('#cPhone').value;m.email=$('#cEmail').value;m.comment=$('#cComment').value;save();openContact(id)}}
const settingsMenu=[['team','Jaktlag','Namn och aktivt jaktår'],['members','Medlemmar','Namn och hektar'],['passes','Pass och områden','Register och GPX-förberedelse'],['history','Jaktår och historik','Starta nästa jaktår'],['data','Data','Backup, import och kontroll']];$('#settingsMenu').innerHTML=settingsMenu.map(x=>`<button onclick="openSetting('${x[0]}')"><b>${x[1]}</b><span>${x[2]}</span></button>`).join('');window.openSetting=k=>{let c=$('#settingsContent');$('#settingsMenu').hidden=true;if(k==='team')c.innerHTML=`<button class="backBtn" onclick="settingsHome()">‹ Inställningar</button><div class="card stackForm"><label>Jaktlagets namn<input id="teamName" value="${esc(db.teamName)}"></label><label>Aktivt jaktår<input id="activeYear" value="${esc(db.activeYear)}"></label><button id="saveTeam">Spara</button></div>`;if(k==='members')c.innerHTML=`<button class="backBtn" onclick="settingsHome()">‹ Inställningar</button><div class="card"><div class="memberEditHead"><span>Medlem</span><span>Hektar</span><span></span></div><div id="memberEdit">${db.members.map(m=>`<div class="memberEditRow"><input data-mn="${m.id}" value="${esc(m.name)}"><input class="hectareInput" data-mh="${m.id}" type="number" min="0" step="0.1" value="${m.hectares}"><button class="danger memberRemove" type="button" onclick="removeMember('${m.id}')">Ta bort</button></div>`).join('')}</div><div class="settingsActions"><button id="addMember">Lägg till medlem</button><button id="saveMembers" class="secondary">Spara medlemmar</button></div></div>`;if(k==='passes')c.innerHTML=`<button class="backBtn" onclick="settingsHome()">‹ Inställningar</button><div class="card stackForm"><input id="passSearch" placeholder="Sök bland pass"><input id="passName" placeholder="Nytt pass"><input id="passArea" placeholder="Område"><button id="addPass">Lägg till pass</button><label class="importButton">Välj GPX-fil<input id="gpxFile" type="file" accept=".gpx"></label><p class="muted">Förberett för kartgräns, kartmarkeringar, koordinater och externa ID:n.</p><div id="passList"></div></div>`;if(k==='history')c.innerHTML=`<button class="backBtn" onclick="settingsHome()">‹ Inställningar</button><div class="card"><p>Aktivt jaktår: <b>${db.activeYear}</b></p><button id="nextYear">Avsluta och starta nästa jaktår</button></div>`;if(k==='data')c.innerHTML=`<button class="backBtn" onclick="settingsHome()">‹ Inställningar</button><div class="card dataActions"><button id="exportJson">Exportera säkerhetskopia</button><label class="importButton">Importera säkerhetskopia<input id="importJson" type="file" accept=".json"></label><button id="validate" class="secondary">Kontrollera datakvalitet</button><button id="reset" class="danger">Radera all appdata</button></div>`;bindSetting(k)};window.settingsHome=()=>{$('#settingsMenu').hidden=false;$('#settingsContent').innerHTML=''};
function auditview(){let a=db.auditLog||[];shell('Händelselogg',a.length?a.map(x=>`<div class="event"><b>${new Date(x.date).toLocaleString('sv-SE')}</b><br>${esc(x.action)}<small>${esc(x.details||'')}</small></div>`).join(''):'<p class="muted">Inga loggade händelser ännu.</p>')}
window.removeMember=id=>{let m=member(id);if(!m)return;let used=db.animals.some(a=>a.recipients.some(r=>String(r.memberId)===String(id)))||db.hunts.some(h=>h.participants.includes(id))||db.observations.some(o=>String(o.observerId)===String(id));if(!confirm(used?'Medlemmen finns i historiken och markeras som inaktiv. Fortsätta?':'Ta bort medlemmen?'))return;if(used){m.active=false;audit('Medlem inaktiverad',m.name)}else{db.members=db.members.filter(x=>x.id!==id);audit('Medlem borttagen',m.name)}save();openSetting('members')}
function bindSetting(k){if(k==='team')$('#saveTeam').onclick=()=>{db.teamName=$('#teamName').value.trim()||db.teamName;db.activeYear=$('#activeYear').value.trim()||db.activeYear;save();toast('Sparat')};if(k==='members'){let render=()=>openSetting('members');$('#addMember').onclick=()=>{db.members.push({id:uid('member'),name:'Ny medlem',hectares:0,phone:'',email:'',comment:''});render()};$('#saveMembers').onclick=()=>{db.members.forEach(m=>{m.name=$(`[data-mn="${m.id}"]`).value;m.hectares=+$(`[data-mh="${m.id}"]`).value||0});save();toast('Medlemmarna sparade')}}if(k==='passes'){let draw=()=>{let q=$('#passSearch').value.toLowerCase();$('#passList').innerHTML=db.passes.filter(x=>x.name.toLowerCase().includes(q)).sort((a,b)=>a.name.localeCompare(b.name)).map(x=>`<div class="recordCard"><div><b>${esc(x.name)}</b><small>${esc(x.area)}</small></div><button onclick="togglePass('${x.id}')">${x.active?'Arkivera':'Aktivera'}</button></div>`).join('')};$('#passSearch').oninput=draw;$('#addPass').onclick=()=>{let n=$('#passName').value.trim();if(!n)return toast('Ange passnamn');db.passes.push({id:uid('pass'),name:n,area:$('#passArea').value.trim(),active:true,latitude:null,longitude:null,externalId:null});save();openSetting('passes')};$('#gpxFile').onchange=e=>{let f=e.target.files[0];if(f){db.mapData.source='gpx:'+f.name;save();toast('GPX-filen registrerad för framtida kartimport')}};draw()}if(k==='history')$('#nextYear').onclick=()=>{let y=+db.activeYear.split('/')[0]+1,open=db.animals.filter(x=>x.year===db.activeYear&&!x.discarded&&x.recipients.reduce((n,r)=>n+(+r.percent||0),0)<100);let msg=open.length?`Det finns ${open.length} ofärdiga fördelningar. De ligger kvar i nuvarande jaktår. Starta nästa jaktår ändå?`:'Starta nästa jaktår?';if(confirm(msg)){db.activeYear=`${y}/${y+1}`;save();openSetting('history')}};if(k==='data'){$('#exportJson').onclick=exportJson;$('#importJson').onchange=importJson;$('#validate').onclick=()=>toast(db.animals&&db.members?'Datakontrollen är godkänd':'Problem hittades');$('#reset').onclick=()=>{if(confirm('Radera all data och återställ standardvärden?')){db=seed();save();go('home')}}}}window.togglePass=id=>{let p=db.passes.find(x=>x.id===id);p.active=!p.active;save();openSetting('passes')};function exportJson(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.download='jaktlaget-1.6.0-backup.json';a.click()}async function importJson(e){try{let f=e.target.files[0];if(!f)return;let d=normalize(JSON.parse(await f.text()));if(confirm('Ersätta lokal data med säkerhetskopian?')){db=d;save();go('home')}}catch{toast('Filen kunde inte importeras')}}
function renderAll(){renderHome();renderHistory();renderStats();if($('#settings').classList.contains('active'))settingsHome()}renderAll();prepareAnimal();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js');
